const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const kabulPoint = ee.Geometry.Point([69.2075, 34.5553]);
    const aoi = kabulPoint.buffer(48280); // 30 miles in meters

    const startDate2017 = '2017-02-01';
    const endDate2017 = '2017-02-28';
    const startDate2018 = '2018-02-01';
    const endDate2018 = '2018-02-28';

    const collectionId = 'MODIS/061/MOD11A1';
    const tempBand = 'LST_Day_1km';

    // 2. Data Acquisition & Processing Function
    const getMeanTemperature = (startDate, endDate, aoi) => {
        const collection = ee.ImageCollection(collectionId)
            .filterDate(startDate, endDate)
            .filterBounds(aoi);

        // Function to mask low-quality pixels
        const maskLST = (image) => {
            const qa = image.select('QC_Day');
            // Bits 0-1: Mandatory QA flags. 00 = LST produced, good quality
            const qualityMask = qa.bitwiseAnd(0b11).eq(0);
            return image.updateMask(qualityMask);
        };

        const maskedCollection = collection.map(maskLST);
        const meanImage = maskedCollection.select(tempBand).mean();

        // Apply scaling factor and convert from Kelvin to Celsius
        const processedImage = meanImage.multiply(0.02).subtract(273.15);

        const stats = processedImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: aoi,
            scale: 1000,
            maxPixels: 1e9
        });

        return {
            stats: stats,
            image_count: collection.size()
        };
    };

    // 3. Calculation for both periods
    const data2017 = getMeanTemperature(startDate2017, endDate2017, aoi);
    const data2018 = getMeanTemperature(startDate2018, endDate2018, aoi);

    const imageCount2017 = data2017.image_count.getInfo();
    const imageCount2018 = data2018.image_count.getInfo();

    if (imageCount2017 === 0 || imageCount2018 === 0) {
        console.log(`Image Count 2017: ${imageCount2017}`);
        console.log(`Image Count 2018: ${imageCount2018}`);
        console.log("Empty image collection for one or both periods.");
        console.log("B"); // A: Yes, B: No
        return;
    }

    const stats2017 = data2017.stats.getInfo();
    const stats2018 = data2018.stats.getInfo();

    const temp2017 = stats2017[tempBand + '_mean'];
    const count2017 = stats2017[tempBand + '_count'];
    const temp2018 = stats2018[tempBand + '_mean'];
    const count2018 = stats2018[tempBand + '_count'];

    console.log(`2017 Image Count: ${imageCount2017}`);
    console.log(`2018 Image Count: ${imageCount2018}`);
    console.log(`2017 Avg Temp (C): ${temp2017 ? temp2017.toFixed(2) : 'N/A'}, Valid Pixels: ${count2017}`);
    console.log(`2018 Avg Temp (C): ${temp2018 ? temp2018.toFixed(2) : 'N/A'}, Valid Pixels: ${count2018}`);

    // 4. Validation & Final Answer
    if (count2017 === 0 || count2018 === 0) {
        console.log("No valid pixels found after cloud/quality masking for one or both periods.");
        console.log("B"); // A: Yes, B: No
        return;
    }

    if (temp2017 === null || temp2018 === null) {
        console.log("Calculation failed, result is null.");
        console.log("B"); // A: Yes, B: No
        return;
    }

    if (temp2018 > temp2017) {
        console.log("A"); // A: Yes, B: No
    } else {
        console.log("B"); // A: Yes, B: No
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
